  --A: #2a78d6;
  --B: #eb6834;
  --push: #9a4fd0;
  --local: #1baf7a;
  --ink: #0b0b0b;
  --ink-2: #52514e;
  --ink-3: #8a8984;
  --line: #e4e3df;
  --sm-bg: #f4f3f0;
  --ce-bg: color-mix(in srgb, var(--fzj-lightblue, #adbde3) 18%, white);
  font-size: 12px;
  line-height: 1.3;
  color: var(--ink);
  text-align: left;
}
html.dark .st {
  --gemm: #a3a29c;
  --ink: #ffffff;
  --ink-2: #c3c2b7;
  --line: #3a3a37;
