  position: absolute; left: 0; writing-mode: vertical-rl; transform: rotate(180deg);
  font-size: 10px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
  text-align: center; color: var(--ink-3); border-right: 2px solid var(--line); padding-right: 0; width: 14px;
}

